请对以下 case 进行三维加权评分。

=== case_id ===
Case-10-rainy-taxi-197

=== 用户原始指令 (query.txt) ===
帮我做个雨天打车卡片看深圳天气和温度，左边是天气信息、右边一个"查看详细天气"按钮按一下跳到天气App。底下横向并排几个小卡显示"排队8人""预计等12分钟"，人数多了标橙色提醒。底色用浅蓝浅灰下雨天的感觉。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我做个雨天打车卡片看深圳天气和温度，左边是天气信息、右边一个\"查看详细天气\"按钮按一下跳到天气App。底下横向并排几个小卡显示\"排队8人\"\"预计等12分钟\"，人数多了标橙色提醒。底色用浅蓝浅灰下雨天的感觉。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.weather",
        "abilityName": "com.huawei.hmos.weather.MainAbility",
        "uri": "weather://city/shenzhen"
      }
    }
  ],
  "dataModel": {
    "value": {
      "taxi": {
        "title": "深圳雨天",
        "weatherText": "小雨",
        "temperatureText": "24°C",
        "queueText": "排队8人",
        "queueLevel": "人数偏多",
        "waitText": "预计等12分钟",
        "actionText": "查看详细天气"
      },
      "assets": {
        "rainIcon": "resources/base/media/icon_weather_rain.png"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "rainIcon",
      "src": "resources/base/media/icon_weather_rain.png",
      "use": "rain weather icon",
      "description": "雨天天气图标，适合在浅蓝浅灰雨天打车卡片中辅助表达深圳小雨天气。",
      "bindTo": "/assets/rainIcon",
      "static": true
    }
  ]
}

